// Pico + W5500 : écrit la mesure du potentiomètre dans le registre 0 de l'automate (Modbus TCP),
// et met la bobine 0 à 1 au-delà de la moitié de la course.
#include <SPI.h>
#include <Ethernet.h>
#include <ArduinoRS485.h>
#include <ArduinoModbus.h>

byte mac[] = { 0xDE, 0xAD, 0xBE, 0xEF, 0xFE, 0x03 };
IPAddress ip(192, 168, 1, 60);         // adresse fixe de la carte
IPAddress automate(192, 168, 1, 50);   // l'Automate Modbus TCP du plan réseau
EthernetClient ethClient;
ModbusTCPClient modbus(ethClient);
unsigned long dernier = 0;

void setup() {
  Serial.begin(115200);
  Ethernet.init(17);                   // CS du W5500 sur GP17
  Ethernet.begin(mac, ip);
}

void loop() {
  if (!modbus.connected()) {
    if (!modbus.begin(automate, 502)) { Serial.println("Automate injoignable"); delay(1000); return; }
  }
  if (millis() - dernier > 1000) {
    dernier = millis();
    int mesure = analogRead(A2);       // A2 = GP28
    if (!modbus.holdingRegisterWrite(0, mesure)) Serial.println(modbus.lastError());
    modbus.coilWrite(0, mesure > 512);
  }
}

